//! Apply autogenerated long foreign-key names to PostgreSQL (issue #6404).

use std::sync::Arc;

use reinhardt_db::backends::DatabaseConnection;
use reinhardt_db::migrations::autodetector::ForeignKeyInfo;
use reinhardt_db::migrations::executor::DatabaseMigrationExecutor;
use reinhardt_db::migrations::model_registry::{FieldMetadata, ModelMetadata};
use reinhardt_db::migrations::{FieldType, ForeignKeyAction, MigrationAutodetector, ProjectState};
use reinhardt_query::prelude::{
	Alias, Expr, ExprTrait, Order, PostgresQueryBuilder, Query, QueryStatementBuilder,
};
use reinhardt_test::fixtures::postgres_container;
use rstest::*;
use sqlx::PgPool;
use testcontainers::{ContainerAsync, GenericImage};

const TABLE: &str = "registry_agent_resource_refs";
const SOURCE: &str = "related_registry_agent_resource_source_id";
const TARGET: &str = "related_registry_agent_resource_target_id";

#[fixture]
fn resource_state() -> ProjectState {
	let mut resources = ModelMetadata::new("registry", "Resource", "registry_agent_resources");
	resources.add_field(
		"id".to_owned(),
		FieldMetadata::new(FieldType::Integer).with_param("primary_key", "true"),
	);
	let mut refs = ModelMetadata::new("registry", "ResourceRef", TABLE);
	refs.add_field(
		"id".to_owned(),
		FieldMetadata::new(FieldType::Integer).with_param("primary_key", "true"),
	);
	for column in [SOURCE, TARGET] {
		refs.add_field(
			column.to_owned(),
			FieldMetadata::new(FieldType::Integer).with_foreign_key(ForeignKeyInfo {
				referenced_table: "registry_agent_resources".to_owned(),
				referenced_column: "id".to_owned(),
				on_delete: ForeignKeyAction::Cascade,
				on_update: ForeignKeyAction::NoAction,
			}),
		);
	}
	let mut state = ProjectState::new();
	state.add_model(resources.to_model_state());
	state.add_model(refs.to_model_state());
	state
}

#[rstest]
#[tokio::test]
async fn generated_long_foreign_keys_apply_and_enforce_both_relations(
	#[future] postgres_container: (ContainerAsync<GenericImage>, Arc<PgPool>, u16, String),
	resource_state: ProjectState,
) {
	// Arrange
	let (_container, pool, _port, url) = postgres_container.await;
	let connection = DatabaseConnection::connect_postgres(&url).await.unwrap();
	let mut executor = DatabaseMigrationExecutor::new(connection);
	let migrations = MigrationAutodetector::new(ProjectState::new(), resource_state)
		.try_generate_migrations()
		.unwrap();

	// Act
	let applied = executor.apply_migrations(&migrations).await.unwrap();

	// Assert
	assert_eq!(applied.failed, None);
	assert_eq!(
		applied.applied,
		migrations.iter().map(|m| m.id()).collect::<Vec<_>>()
	);
	let query = Query::select()
		.column(Alias::new("constraint_name"))
		.from((
			Alias::new("information_schema"),
			Alias::new("table_constraints"),
		))
		.and_where(Expr::col(Alias::new("table_schema")).eq("public"))
		.and_where(Expr::col(Alias::new("table_name")).eq(TABLE))
		.and_where(Expr::col(Alias::new("constraint_type")).eq("FOREIGN KEY"))
		.order_by(Alias::new("constraint_name"), Order::Asc)
		.to_string(PostgresQueryBuilder);
	let names: Vec<String> = sqlx::query_scalar(&query)
		.fetch_all(pool.as_ref())
		.await
		.unwrap();
	assert_eq!(
		names,
		vec![
			"fk_registry_agent_resource_refs_related_regist_74dadaa1f5257db3",
			"fk_registry_agent_resource_refs_related_regist_9d7b7fa9ada59fef",
		]
	);

	let insert_resource = Query::insert()
		.into_table(Alias::new("registry_agent_resources"))
		.columns([Alias::new("id")])
		.values_panic([1])
		.to_string(PostgresQueryBuilder);
	assert_eq!(
		sqlx::query(&insert_resource)
			.execute(pool.as_ref())
			.await
			.unwrap()
			.rows_affected(),
		1
	);
	for (id, source, target, expected_constraint) in [
		(1, 1, 1, None),
		(
			2,
			999,
			1,
			Some("fk_registry_agent_resource_refs_related_regist_9d7b7fa9ada59fef"),
		),
		(
			3,
			1,
			999,
			Some("fk_registry_agent_resource_refs_related_regist_74dadaa1f5257db3"),
		),
	] {
		let query = Query::insert()
			.into_table(Alias::new(TABLE))
			.columns([Alias::new("id"), Alias::new(SOURCE), Alias::new(TARGET)])
			.values_panic([id, source, target])
			.to_string(PostgresQueryBuilder);
		let result = sqlx::query(&query).execute(pool.as_ref()).await;
		if let Some(expected_constraint) = expected_constraint {
			let error = result.unwrap_err();
			let database_error = error.as_database_error().unwrap();
			assert_eq!(database_error.code().as_deref(), Some("23503"));
			assert_eq!(database_error.constraint(), Some(expected_constraint));
		} else {
			assert_eq!(result.unwrap().rows_affected(), 1);
		}
	}

	let rollback = executor.rollback_migrations(&migrations).await.unwrap();
	assert_eq!(rollback.failed, None);
	assert_eq!(rollback.applied, applied.applied);
}
